// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetLibraryCounts Count the library by view, kind and unread state
	// (GET /api/library/counts)
	GetLibraryCounts(ctx context.Context, request GetLibraryCountsRequestObject) (GetLibraryCountsResponseObject, error)
	// ListLibraryDomainRuleSuggestions List the suggested domain rules
	// (GET /api/library/domain-rule-suggestions)
	ListLibraryDomainRuleSuggestions(ctx context.Context, request ListLibraryDomainRuleSuggestionsRequestObject) (ListLibraryDomainRuleSuggestionsResponseObject, error)
	// DismissLibraryDomainRuleSuggestion Dismiss a suggested domain rule
	// (POST /api/library/domain-rule-suggestions/{domain}/dismiss)
	DismissLibraryDomainRuleSuggestion(ctx context.Context, request DismissLibraryDomainRuleSuggestionRequestObject) (DismissLibraryDomainRuleSuggestionResponseObject, error)
	// ListLibraryDomainRules List the domain rules
	// (GET /api/library/domain-rules)
	ListLibraryDomainRules(ctx context.Context, request ListLibraryDomainRulesRequestObject) (ListLibraryDomainRulesResponseObject, error)
	// DeleteLibraryDomainRule Remove a domain rule
	// (DELETE /api/library/domain-rules/{domain})
	DeleteLibraryDomainRule(ctx context.Context, request DeleteLibraryDomainRuleRequestObject) (DeleteLibraryDomainRuleResponseObject, error)
	// SetLibraryDomainRule Create or replace a domain rule
	// (PUT /api/library/domain-rules/{domain})
	SetLibraryDomainRule(ctx context.Context, request SetLibraryDomainRuleRequestObject) (SetLibraryDomainRuleResponseObject, error)
	// ListLibraryItems List saved links
	// (GET /api/library/items)
	ListLibraryItems(ctx context.Context, request ListLibraryItemsRequestObject) (ListLibraryItemsResponseObject, error)
	// SaveLibraryItem Save a link to the library
	// (POST /api/library/items)
	SaveLibraryItem(ctx context.Context, request SaveLibraryItemRequestObject) (SaveLibraryItemResponseObject, error)
	// DrawLibraryItems Draw a random unread item
	// (GET /api/library/items/random)
	DrawLibraryItems(ctx context.Context, request DrawLibraryItemsRequestObject) (DrawLibraryItemsResponseObject, error)
	// DeleteLibraryItem Delete a saved link and everything written on it
	// (DELETE /api/library/items/{id})
	DeleteLibraryItem(ctx context.Context, request DeleteLibraryItemRequestObject) (DeleteLibraryItemResponseObject, error)
	// GetLibraryItem Read one saved link in full
	// (GET /api/library/items/{id})
	GetLibraryItem(ctx context.Context, request GetLibraryItemRequestObject) (GetLibraryItemResponseObject, error)
	// PatchLibraryItem Change a saved link
	// (PATCH /api/library/items/{id})
	PatchLibraryItem(ctx context.Context, request PatchLibraryItemRequestObject) (PatchLibraryItemResponseObject, error)
	// ExtractLibraryItem Extract a saved link's article text again
	// (POST /api/library/items/{id}/extract)
	ExtractLibraryItem(ctx context.Context, request ExtractLibraryItemRequestObject) (ExtractLibraryItemResponseObject, error)
	// OpenLibraryItem Record that a saved link was opened
	// (POST /api/library/items/{id}/open)
	OpenLibraryItem(ctx context.Context, request OpenLibraryItemRequestObject) (OpenLibraryItemResponseObject, error)
	// AddLibraryItemTag Tag a saved link by hand
	// (POST /api/library/items/{id}/tags)
	AddLibraryItemTag(ctx context.Context, request AddLibraryItemTagRequestObject) (AddLibraryItemTagResponseObject, error)
	// RemoveLibraryItemTag Remove a tag from a saved link by hand
	// (DELETE /api/library/items/{id}/tags/{name})
	RemoveLibraryItemTag(ctx context.Context, request RemoveLibraryItemTagRequestObject) (RemoveLibraryItemTagResponseObject, error)
	// ListLibraryTags List the library's tags
	// (GET /api/library/tags)
	ListLibraryTags(ctx context.Context, request ListLibraryTagsRequestObject) (ListLibraryTagsResponseObject, error)
	// PatchLibraryTag Rename one tag across the library
	// (PATCH /api/library/tags/{name})
	PatchLibraryTag(ctx context.Context, request PatchLibraryTagRequestObject) (PatchLibraryTagResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

